\begin{equation*}
 \rep{\identity}{B,D}=
 \begin{pmat}{c@{\hspace{1em}}c@{\hspace{1em}}c}
 \vdots & &\vdots \\
 \rep{\vec{\beta}_1}{D} &\;\cdots\; &\rep{\vec{\beta}_n}{D} \\
 \vdots & &\vdots
 \end{pmat}
\end{equation*}

