 \begin{pmatrix}c_1 \\ \vdots \\ c_n\end{pmatrix}
 =
 \colvec{a_{1,1}c_1+\dots+a_{1,n}c_n \\
 a_{2,1}c_1+\dots+a_{2,n}c_n \\
 \vdots \\ 
 a_{m,1}c_1+\dots+a_{m,n}c_n}
\end{equation*}

