text:
If
\begin{equation*}
 T=\begin{pmatrix}
 1 &0 &4 \\
 2 &1 &-1 \\
 1 &0 &1
 \end{pmatrix}
\end{equation*}
then $\adj(T)$ is
\begin{equation*}
 \begin{pmatrix}
 T_{1,1} &T_{2,1} &T_{3,1} \\
 T_{1,2} &T_{2,2} &T_{3,2} \\
 T_{1,3} &T_{2,3} &T_{3,3} 
 \end{pmatrix}
 \!\!=\!\!\begin{pmatrix}
 \begin{vmat}[r]
 1 &-1 \\
 0 &1
 \end{vmat}
 &-\begin{vmat}[r]
 0 &4 \\
 0 &1
 \end{vmat}
 &\begin{vmat}[r]
 0 &4 \\
 1 &-1
 \end{vmat} \\[2.1ex]
 -\begin{vmat}[r]
 2 &-1 \\
 1 &1
 \end{vmat}
 &\begin{vmat}[r]
 1 &4 \\
 1 &1
 \end{vmat}
 &-\begin{vmat}[r]
 1 &4 \\
 2 &-1
 \end{vmat} \\[2.1ex]
 \begin{vmat}[r]
 2 &1 \\
 1 &0
 \end{vmat}
 &-\begin{vmat}[r]
 1 &0 \\
 1 &0
 \end{vmat}
 &\begin{vmat}[r]
 1 &0 \\
 2 &1
 \end{vmat}
 \end{pmatrix}
 \!\!=\! 
 \begin{pmatrix}
 1 &0 &-4 \\
 -3 &-3 &9 \\
 -1 &0 &1
 \end{pmatrix} 
\end{equation*}
and taking the product with $T$ gives the diagonal matrix $\deter{T}\cdot I$.
\begin{equation*}
 \begin{pmatrix}
 1 &0 &4 \\
 2 &1 &-1 \\
 1 &0 &1
 \end{pmatrix}
 \begin{pmatrix}
 1 &0 &-4 \\
 -3 &-3 &9 \\
 -1 &0 &1
 \end{pmatrix} 
 =\begin{pmatrix}
 -3 &0 &0 \\
 0 &-3 &0 \\
 0 &0 &-3
 \end{pmatrix}
\end{equation*}
\noindent The inverse of $T$ 
is $(1/-3)\cdot\adj(T)$.
\begin{equation*}
 T^{-1}
 =\begin{pmatrix} 
 1/\hbox{$-3$} &0/\hbox{$-3$} &-4/\hbox{$-3$} \\
 -3/\hbox{$-3$} &-3/\hbox{$-3$} &9/\hbox{$-3$} \\
 -1/\hbox{$-3$} &0/\hbox{$-3$} &1/\hbox{$-3$}
 \end{pmatrix}
 =\begin{pmatrix}
 -1/3 &0 &4/3 \\
 1 &1 &-3 \\
 1/3 &0 &-1/3
 \end{pmatrix}
\end{equation*}

